[PostHandlerFor(classStr(LeaveRequestAmountHelper), staticMethodStr(LeaveRequestAmountHelper, calculateDefaultRequestAmounts))]
public static void LeaveRequestAmountHelper_Post_calculateDefaultRequestAmounts(XppPrePostArgs args)
{
    LeaveTypeRecId leaveTypeRecId = args.getArg(identifierStr('_leaveType'));
    LeaveType leaveType = LeaveType::findLeaveTypeByCrossCompanyFeature(leaveTypeRecId);

    if(leaveType.LeaveAmountUnit == LeaveAmountUnit::Days)
    {
        Map defaultRequestAmounts = new Map(Types::Date, Types::Real);
        Map defaultValueMap = args.getReturnValue();
        MapEnumerator defaultValueMapEnum = defaultValueMap.getEnumerator();

        while(defaultValueMapEnum.moveNext())
        {
            Amount amount = defaultValueMapEnum.currentValue();

            if(amount == 0)
                amount = 1;

            defaultRequestAmounts.insert(defaultValueMapEnum.currentKey(), amount);
        }

        args.setReturnValue(defaultRequestAmounts);
    }
}
